<?php
namespace App\Console\Commands;
use App\Models\MediaAsset; use App\Services\LegacyMediaReader; use Illuminate\Console\Command; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\File; use Illuminate\Support\Facades\Storage;
class LegacyMigrateMediaCommand extends Command {protected $signature='legacy:migrate-media {--ids=} {--dry-run} {--apply} {--out=docs/generated/media-migration-sample}';public function handle(LegacyMediaReader $reader):int{$ids=array_filter(array_map('intval',explode(',',(string)$this->option('ids'))));if(!$ids||count($ids)>10||($this->option('dry-run')&&$this->option('apply'))){$this->error('Use 1-10 explicit IDs and one mode.');return self::FAILURE;}$r=['mode'=>$this->option('apply')?'apply':'dry-run','items'=>[]];foreach(DB::connection('legacy_wp')->table('posts')->whereIn('ID',$ids)->where('post_type','attachment')->get() as $a){try{$x=$reader->inspect($a->guid);$item=['legacy_attachment_id'=>$a->ID,'source_present'=>true,...$x];if($this->option('apply')){$name='media/originals/'.$x['checksum'].'.'.pathinfo($x['source'],PATHINFO_EXTENSION);$asset=MediaAsset::firstOrCreate(['checksum'=>$x['checksum']],['legacy_attachment_id'=>$a->ID,'original_path'=>$name,'mime'=>$x['mime'],'width'=>$x['width'],'height'=>$x['height'],'bytes'=>$x['bytes'],'alt_text'=>$a->post_excerpt]);if(!Storage::disk(config('legacy-media.disk'))->exists($name))Storage::disk(config('legacy-media.disk'))->put($name,file_get_contents($x['source']));$item['destination']=$asset->original_path;}$r['items'][]=$item;}catch(\Throwable $e){$r['items'][]=['legacy_attachment_id'=>$a->ID,'source_present'=>false,'anomaly'=>'missing_or_invalid_source'];}}$b=base_path($this->option('out'));File::put($b.'.json',json_encode($r,JSON_PRETTY_PRINT));File::put($b.'.md','# Media migration pilot\n\n```json\n'.json_encode($r,JSON_PRETTY_PRINT).'\n```\n');return self::SUCCESS;}}
